-- The 39 spells of Living Fire Magic, the Russian Fire Sorcerer's tradition.
-- Rifts World Book 18: Mystic Russia pp.111-118. Batch 1c of the mystic-russia
-- ingestion, and THE ONE DECISION D1 WAS ARGUED OVER.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzz-mr-living-fire-spells.sql
--
-- Read from the book's TEXT LAYER (.cache/books/mystic-russia, page_offset 1)
-- by the same reader that produced the Spoiling and Bone batches.
--
-- THIS IS WHERE THE COLLISIONS ARE, and why D1 exists. 14 of these 39 share a
-- name with something the catalog already holds, and the survey's withdrawn
-- "five spells disagree on level" reading came from reading that overlap as a
-- conflict. It is not one. The catalog already holds a tradition's version of a
-- spell as its OWN row at its OWN level beside the common invocation -
-- `Fire: Circle of Flame` is level 3 where `Circle of Flame` is 5 - and these
-- rows join that pattern rather than competing with it. NO EXISTING ROW CHANGES
-- VALUE.
--
-- 13 rows carry `same_spell_as`, pointing at the established row by name,
-- following `Air: Sonic Blast` -> `Sonic Blast`. Each keeps its own level and
-- cost. Two of the 13 are judgement rather than a name match, and both are
-- said out loud here:
--
--   * `Fire Fists` is linked to `Fire Fist` (Palladium Fantasy Main Book
--     p.199). Same magic, published twice: this one is level 3 and costs 8 and
--     burns BOTH hands for M.D., that one is level 6 and costs 15 and burns one
--     fist for S.D.C. The catalog already links across a singular/plural
--     difference - `Ocean: Communicate with Sea Creature` points at
--     `Water: Communicate with Sea Creatures` - so the plural is not the
--     obstacle; the judgement is that they are the same spell at all.
--   * `Fumigate: Insects` is deliberately NOT linked, though a normaliser that
--     strips any `Word: ` prefix matches it to `Metamorphosis: Insect`. It is a
--     false positive - one spell drives insects out of a building, the other
--     turns the caster into one - and it is recorded here because the same
--     normaliser will offer it again.
--
-- ONE NAME IS NORMALISED: the book heads this spell `Cloud Of Smoke`, with a
-- capital `Of` that it uses nowhere else - `Circle of Flame`, `Bonfire of
-- Purification` and `Armor of Svarozhich` are all lower-case on the same pages.
-- Stored as `Cloud of Smoke`, which is also the catalog's spelling of the row it
-- points at.
--
-- `tradition = 'living-fire'` is its own value and the FIRST hyphenated one
-- here. It is deliberately not `fire`: the catalog's `Fire:` family are WARLOCK
-- spells and carry `tradition = 'warlock'`, so `fire` would read as a claim that
-- these are the same tradition. They are not - this one belongs to the Russian
-- Fire Sorcerer, and the gate decides which classes reach it.
--
-- Levels run L1:5 L2:5 L3:6 L4:6 L5:5 L6:4 L7:4 L8:1 L9:2 L12:1. THE BOOK JUMPS from Level Nine to Level Twelve, with no
-- Ten or Eleven - verified against every `Level N` heading in the band, the
-- same shape as Spoiling Magic having no Level Nine. Nothing was dropped.
--
-- 7 costs are schedules rather than plain numbers, and most are this
-- book's own two-tier pricing: "6 for Fire Sorcerers, 10 for other
-- practitioners of magic". `ppe` holds the FIRE SORCERER price, because this row
-- is the Fire Sorcerer's tradition, and `ppe_note` carries the full schedule.

INSERT INTO spells
  (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition)
VALUES
  ('Living Fire: Cloud of Smoke', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.111', 'rifts', '90 feet (27.4 m)', 'One minute per level of experience.', NULL, 'None', NULL, NULL, 'This magic enables the arcanist to create a cloud of dense, black smoke (30x30x30 feet/9 m maximum size) up to ninety feet (27.4 m) away. Victims caught in the cloud will be unable to see anything beyond the cloud, and their impaired vision allows them to see no more than three feet (0.9 m) inside it, and only blurry shapes. While in the cloud, victims will be -5 to strike, parry and dodge. The smoke may make people cough, but does not cause damage and once out of the cloud, people recover in a few seconds.', 'Cloud of Smoke', 'living-fire'),
  ('Living Fire: Finger Sparks', 1, 2, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.111', 'rifts', 'Self', 'The ability lasts for one melee round (15 seconds) per level of the caster. The small flurry of sparks lasts about one second.', NULL, 'Not applicable.', NULL, NULL, 'Note: This is considered "used" fire. Each snap of the fingers counts as one melee action. The sorcerer can cause sparks to fly every time he snaps his fingers. This can be done to entertain (like a magic trick or sparklers) or to attempt to light a fire. Sparks hitting highly combustible material (nylon, gasoline, turpentine, lamp oil, gunpowder, etc.) a 0-80% likelihood of igniting it. Sparks hitting moderately combustible materials like a cigarette, cigar, candle wick, clothing, rags, hair, wood, paper, etc.) A 0-40% chance of starting it on fire. Zero chance of starting human flesh, meat, healthy grass or plants on fire.', NULL, 'living-fire'),
  ('Living Fire: New Fire', 1, 1, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.111', 'rifts', 'Touch and requires two sticks', 'Results in one melee round (uses up all melee actions for that round); the fire lasts as long as it is nurtured.', NULL, 'Not applicable.', NULL, NULL, 'This spell enables the sorcerer to flawlessly create magic fire by rubbing two sticks together; i.e. using friction to create a new, pure fire "bom of wood," rather than getting it from another fire or some other means. The new fire generated from the rubbing of two sticks will light a fire (torch, campfire, fireplace, bonfire, etc.) without fail, even in a strong wind. Once started, the fire must be normally maintained. This fire born of wood is considered "chistyi" (pure) for use in purification rites and magic, as well as for building normal fires.', NULL, 'living-fire'),
  ('Living Fire: Pluck & Handle Flame', 1, 4, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.111', 'rifts', 'Self/touch.', 'One minute per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'Note: This is "used" or second-hand fire. The spell caster can pluck the flame from a candle, torch or lantern, or snatch a small tongue of flame from a fireplace, campfire or other large fire, and handle it as if it were a substantive thing. The tiny to small tongue of fire continues to burn on the sorcerer''s finger or hand without injury to the mage and without any apparent energy source. The mage can carry the fire around on his finger or hand, place it on his shoulder or head, and even put it in his pocket without it spreading. This can be continued for the full duration of the spell. Before the spell elapses, the flame must be returned from whence it came or placed on a new source of energy (i.e. another candle, lantern, piece of wood, fireplace, etc.), otherwise it will simply vanish; magically extinguished. While in hand, the flame can be used like a candle or torch to light the way, or to light a different candle, torch, oven, etc. However, when used to light something else, the entire "plucked" flame goes to that new place or item to burn (the item where the fire originated is undamaged and can be relit by hand to get it going again). The sorcerer can even make the tongue of flame leap from one hand to the other, or from the top of his head or shoulder back to his hand, but it cannot jump out of his hand onto something or someone else; the mage must physically place it there. Cupping the flame in both hands or putting it inside his mouth and closeing it, extinguishes it.', NULL, 'living-fire'),
  ('Living Fire: Smoke Smell', 1, 1, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', 'Can be cast up to 100 feet (30.5 m) away.', 'Two minutes per level of experience.', NULL, 'None', NULL, NULL, 'This magic creates the unmistakable smell of something burning. The smell can be made to come from one particular object (oven, box, computer, engine, generator, wall socket, etc.) or to permeate one particular room or vehicle. This is a distraction and confusion causing spell that should get everybody who smells it looking around in search of the cause in order to prevent a fire. While distracted, the spell caster and his companions are +15% to prowl/sneak past the people searching for the cause of the burning smell, plus those searching are slow to react, -2 on initiative. Level Two', NULL, 'living-fire'),
  ('Living Fire: Bright Sun', 2, 5, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', 'Can be cast up to 300 feet (91 m) away and has a radiance that fills a 100 foot (30.5 m) diameter with bright light.', 'Lasts five minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'A spell that creates a brilliant light radiating from a small magical sphere. Despite its brightness, those looking into it are not blinded or harmed, unless they are demons. Vampires, undead and other demonic supernatural beings are blinded by the light (-9 to strike, parry and dodge for 1D6 melee rounds) and recoil from it. Il''ya demons, the Unclean, ghouls, Succubus or Incubus and others vulnerable to the light of day are forced to assume their true demonic form and retain only the P.S. and M.D.C. they have during the day. This spell is effectively a more powerful Globe of Daylight, except the sphere of light cannot be moved once it appears.', NULL, 'living-fire'),
  ('Living Fire: Column of Smoke', 2, 3, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', 'Up to 90 feet (27.4 m) away.', 'Two minutes per level of experience.', NULL, 'None', NULL, NULL, 'The sorcerer can create a narrow, spiralling column of white smoke that rises up into the air 12 feet (3.6 m) per level of his experience. This smoke is typically used like a ladder for climbing. It can also be used as a signal. See the Climb Smoke spell.', NULL, 'living-fire'),
  ('Living Fire: Extinguish Fire', 2, 4, '4 (putting in 8 P.P.E. doubles the range and duration).', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', '20 foot (6 m) area, up to 80 feet (24.4 m) away.', 'One minute (4 melee rounds) per level of experience.', NULL, 'None', NULL, NULL, 'The mage can instantly put out up to a 20 foot (6 m) diameter of fire 80 feet away (24.4 m). A total of 40 feet (12.2 m) can be extinguished every 15 seconds (one melee).', 'Extinguish Fire', 'living-fire'),
  ('Living Fire: Locate & Identify Fire', 2, 4, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', 'Self, but sensing range is 1000 feet (305 m) per level of experience.', 'Five minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The spell caster can sense if fire is within the radius of his sensing range. He can also tell if there is one, a few, several, or many (the latter two probably indicating a town), and the general direction of the fire(s), as well as whether the fire is burning out of control. This power also enables the mage to accurately determine the heat emitted by a fire, estimate how long ago a fire burned and whether it was natural, magical, or deliberately set, by examining the remains of a fire.', NULL, 'living-fire'),
  ('Living Fire: Toxic Smoke Cloud', 2, 5, '5 for the standard cloud, 10 P.P.E. to double the size and or range.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', '90 feet (27.4 m)', 'One minute per level of experience.', NULL, 'None', NULL, NULL, 'This magic enables the sorcerer to create a billowing cloud of burning and choking grey and black smoke (30x30x30 feet/9 m maximum size) up to ninety feet (27.4 m) away. Victims caught in the cloud will find it difficult to breathe. Unless protected by an air filter and goggles, or environmental armor, those caught in the smoke suffer 2D6 Hit Point/S.D.C. damage for every mer lee round they are trapped in the smoke, and can barely see (no initiative, no sense of direction, -1 melee attack/action and -6 to strike, parry, and dodge); can not see outside the cloud. Note: The penalties from the toxins remain for 1D4 melee rounds after the victims manage to find their way out of the toxic cloud. Mega-Damage creatures will not suffer damage but will have difficulty seeing (roughly equal to the previous Cloud of Smoke spell) and suffer half the penalties. People who see the smoke from a distance will assume there is a fire. Level Three', NULL, 'living-fire'),
  ('Living Fire: Circle of Flame', 3, 6, '6 for Fire Sorcerers, 10 for other magic O.C.C.s.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', '10 feet (3 m) around self.', '2 minutes per level of experience.', NULL, 'None', NULL, NULL, 'The mage can create a circle of flame around himself. No combustible material is required. The flame is five feet (1.5 m) tall and inflicts 6D6 S.D.C. damage or 1D4 M.D. to anybody who tries to pass through the fire.', 'Circle of Flame', 'living-fire'),
  ('Living Fire: Fire Fists', 3, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.112', 'rifts', 'Empowers self only. Inflicts damage by touch.', 'One melee round per level of the spell caster.', '1D6 M.D. +1 additional M.D. per level of experience (no P.S. damage applies unless it is from supernatural P.S.). In the alternative, the mage can will the flames to inflict S.D.C. damage in increments of 2D6 up to 6D6 S.D.C.', 'Dodge punch.', NULL, NULL, 'The hands of the spell caster appear to be engulfed in fire, however, the flames only burn targets the sorcerer desires to damage.', 'Fire Fist', 'living-fire'),
  ('Living Fire: Insect Chaser', 3, 5, '5 for Fire Sorcerers, 10 for other magic O.C.C.s.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.113', 'rifts', 'Affects a 100 foot (30.5 m) diameter per level of the spell caster.', 'Instant results; the fumes and its magic linger for 30 minutes per level of the spell caster.', NULL, 'None', NULL, NULL, 'A nice smelling wood or incense is lit with a "New Fire" and the Insect Chaser spell cast. The pleasant, light aroma keeps biting insects and crop devouring bugs away. Affects a 100 foot (30.5 m) diameter per level of the spell caster.', NULL, 'living-fire'),
  ('Living Fire: Ignite Fire', 3, 3, '3 for Fire Sorcerers, 6 for other magic O.C.C.s.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.113', 'rifts', '40 feet (12.2m)', 'Instant results (counts only as one attack; fire lasts until it is put out).', NULL, 'None', NULL, NULL, 'Note: This is not "New Fire." A magic that cause spontaneous combustion. The magic will ignite any material that can burn. This means the mystic could set a chair on fire, a jacket, hair, and so on. Note: Volatile substances that are contained in something, like gasoline in the gas tank of a car, can NOT be ignited. The target to be set on fire must be clearly visible. Maximum area of affect is 3 feet (0.9 m). If somebody''s clothes or hair are set on fire, they have two melees (30 seconds) to get it off or put the fire out before damage is inflicted; no other combat or action is possible. Damage from the small fire is 2D6 S.D.C. per melee (beginning after the first 2 melees).', 'Ignite Fire', 'living-fire'),
  ('Living Fire: Impervious to Fire', 3, 5, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', 'Self or one other up to 60 feet (18.3 m) away; line of sight.', '5 minutes per level of experience.', NULL, 'None', NULL, NULL, 'A magic invocation that makes the individual temporarily impervious to all types of fire. M.D. plasma, napalm, and normal and magical fires do no damage to the person or to anything he is wearing/on his person.', 'Impervious to Fire', 'living-fire'),
  ('Living Fire: M.D. Torchfire', 3, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', 'Touch; close, hand to hand combat.', 'Two minutes per level of experience.', '2D6 M.D.', 'Not applicable.', NULL, NULL, 'The spell transforms an ordinary, lit S.D.C. torch into a fire that does Mega-Damage. The torch can be used as a jabbing or clubbing weapon, with the fire doing 2D6 damage to whomever is struck. The fire stays at the top of the torch and does not set anything on fire. When the magic is over, it returns to being an ordinary torch. Level Four', NULL, 'living-fire'),
  ('Living Fire: Blessing from Svarozhich', 4, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', 'A blessing cast on a particular individual who must be present when the magic is performed or within a half mile (0.8 km).', 'One hour per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The spell is cast and a sheath of corn is tossed into a fire where it burns and brings luck. The luck can be cast upon the spell caster or one character of his choice. Those endowed with the Blessing of Svarozhich can handle or work around fire without fear of injury or misfortune (no accidental fires, burns, mistakes, etc.). Furthermore, M.D. fire attacks leveled against the blessed individual do half damage, and the blessed one is impervious to normal fire and heat, and +3 to save vs illnesses that cause fever.', NULL, 'living-fire'),
  ('Living Fire: Climb Smoke', 4, 8, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', 'Self or one other by touch.', 'Four minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'This spell enables the spell caster (or one other enchanted by touch) to climb up billowing clouds or strands of smoke as if it were as solid as earth. The climbing skill is 85%/80%.', NULL, 'living-fire'),
  ('Living Fire: Fireblast', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', '50 feet (15.2m)', 'Instant', '3D6 M.D.', 'Dodge', NULL, NULL, 'Fireblast is a simple offensive spell in which the mage shoots mega-damage flames from his or her hands. The blast is only one foot (0.3 m) wide, but extends for the full 50 feet (15.2 m). Everything in its path will take damage unless those in its path can dodge. The blast can be stopped by doors, walls, etc., but only if the spell''s damage does not destroy the object. Otherwise, the flames keep going. This is a great spell for clearing out passageways.', 'Fireblast', 'living-fire'),
  ('Living Fire: Fire Bolt', 4, 7, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', '100 feet (30.5 m) +5 feet (1.5 m) per level of experience.', 'Instant', '4D6 M.D.', 'Dodge', NULL, NULL, 'The mage can create and direct a bolt of fire. Bonus to strike is +4. Damage is normally 4D6 M.D., or !D6xlO S.D.C. (the mage can adjust the damage to be S.D.C. or M.D.).', 'Fire Bolt', 'living-fire'),
  ('Living Fire: Fire Shield', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.114', 'rifts', 'Hand to hand combat.', 'Three melee rounds per level of experience.', '1D4 M.D. by touch.', 'Dodge', NULL, NULL, 'The sorcerer creates a shield of living flame. The shield can be used like a physical object to parry attacks, but is so hot and intimidating that the attacker(s) is -2 to strike and parry. Furthermore, unless a hand-held weapon is large and the attacker does not lean into the flames of the Fire Shield, the attacker will take 1D4 M.D. from the heat and flame of the shield. In addition, the user of the shield is impervious to normal flame, while magic fire and M.D. flames do half damage.', NULL, 'living-fire'),
  ('Living Fire: Fire Meld', 4, 10, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', '60 feet (18.3 m) +10 feet (3 m) per level of experience.', 'One minute per level of the Fire Sorcerer.', NULL, 'Not applicable.', NULL, NULL, 'The spell caster can make himself completely disappear by stepping into a fire. The concealing flame must be at least as big as a campfire, with bonfires and larger being ideal. Inside the sheltering fire, no form of magical or man-made detection can detect or locate the-mage. Furthermore, shooting through or stabbing into the flame has no effect on the mage who is now part of the living fire. However, the sorcerer within can not take action, speak, or attack without stepping out of the fire. Waiting silently and patiently can be difficult, especially when the fire also obscures the vision and hearing of the one hidden inside the fire. Stepping out of the fire makes that individual reappear. Dowsing the fire with water, putting out the flame, will reveal the sorcerer drenched in water. Level Five', NULL, 'living-fire'),
  ('Living Fire: Armor of Svarozhich', 5, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', 'Self', 'One minute per level of the spell caster.', NULL, 'Not applicable. M.D.C. of the Armor: 12 points per level of the spell caster.', NULL, NULL, 'Within seconds, the character is covered with a suit of chain mail armor that appears to be made of molten metal that is still red hot. The wearer is impervious to heat and fire, including M.D. plasma and magical fire, plus the suit offers M.D. protection from physical attacks. Those who touch the armor will be burned, suffering 4D6 S.D.C. damage.', NULL, 'living-fire'),
  ('Living Fire: Bonfire of Purification', 5, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', 'Touch and requires "New Fire."', 'Results in one melee round; the fire lasts as long as it is nurtured (i.e. wood is added, the fire stoked, etc.), up to 48 hours.', NULL, 'Not applicable.', NULL, NULL, 'First a New Fire must be made (uses up all the melee actions for one round). Once the "pure" flame is created, it is used to light a bonfire while the sorcerer casts his second spell to create a Bonfire of Purification. The magic causes the wood for the bonfire to ignite immediately and completely into a raging (but controlled) fire. This spell creates a magical, purifying fire in which any corpse thrown into it is incinerated in one minute; only ash remains! Furthermore, any disease the bodies may have harbored is completely destroyed, and the bodies of victims of a vampire''s bite (before they are reborn as a vampire) can be destroyed without fear of them returning as the living dead. Furthermore, any food cooked in the fire or water or beverage boiled by the fire will be made clean of any disease, including food or drink magically "spoiled."', NULL, 'living-fire'),
  ('Living Fire: Fire Ball', 5, 6, '6 for Fire Sorcerers, 10 for other magic O.C.C.s.', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', '90 feet (27.4 m) - +20 feet (6 m) per level of experience for Fire Sorcerers.', 'Instant', '1D4 M.D. per level of the spell caster.', 'None except dodge, but the victim must know the attack is coming and must roll an 18 or higher.', NULL, NULL, 'The spell caster creates a large fire ball which hurls at its target at an awesome speed, inflicting 1D4 Mega-Damage points of damage per each level of the spell caster. The fire ball is magically directed and seldom misses.', 'Fire Ball', 'living-fire'),
  ('Living Fire: Fumigate: Insects', 5, 12, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', 'Touch; close, hand to hand combat.', 'Two minutes per level of experience.', 'Kills insect pests.', 'Not applicable.', NULL, NULL, 'This spell creates a thick grey cloud of smoke that has a tinge of sulfur to it. Indoors, the cloud will fill and cover a 1000x1000 foot area (305x305 meters). Outdoors, the cloud hangs low to the ground and is blown by the wind, brushing over 10 times the area it covers indoors, but dissipates twice as fast. Everything the cloud covers for more than 15 seconds will see the fumes kill insect pests, including fleas, lice, mites, ticks, locusts, and crop eating bugs.', NULL, 'living-fire'),
  ('Living Fire: Spiral Fire Blast', 5, 15, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', '60 feet (18.3 m) +10 feet (3 m) per level of experience.', 'Instant', 'Varies.', 'Dodge at -2.', NULL, NULL, 'A conical blast of fire that appears in the shape of a spiralling coil of fire that is tapered at the hands of the sorcerer, but enlarges to end in a diameter of eight feet (2.4 m) at the point of impact. Everything that touches at the edge of the fire takes 1D6 M.D. but the main target at the end and center of the spiral blast takes 3D6 M.D. plus 1D6 M.D. per level of experience! Level Six', NULL, 'living-fire'),
  ('Living Fire: Fire Blossom', 6, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.115', 'rifts', 'Touch; appears above the open palm of the mage''s hand.', 'One month per level of the spell caster, but bums out within 1D6 minutes after it is activated.', 'Varies', 'None', NULL, NULL, 'This is a unique spell in which the mage creates a Fire Blossom - a small tongue of flame (about three inches tall). It flickers but does not bum and can be held, put in one''s pocket or placed in a bag or backpack without fear of starting a fire. The fire does not burn until the mage or the recipient of the Fire Blossom (it can be created and given as a gift) activates it. Once done, the Fire Blossom bursts into a raging fire three feet (0.9 m) tall and two feet (0.6 m) wide. It will burn without combustibles (wood, rags, coal, etc.) for 1D6 minutes and then vanishes. If placed on or stoked with combustibles, these items will immediately catch fire and burn, thus the Fire Blossom can be used to create a campfire, light torches, or to start a fire.', 'Fire Blossom', 'living-fire'),
  ('Living Fire: Fire Sword', 6, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.116', 'rifts', 'Touch; close, hand to hand combat.', 'One minute per level of experience.', '4D6 M.D. (only 1D6 M.D. to foes impervious to fire).', 'Not applicable.', NULL, NULL, 'The spell transforms an ordinary S.D.C. sword of any size or type into a magical blade of steel and flame! After creating it, the spell caster can give the sword to someone else, if he so desires. The weapon functions as a magical sword by stabbing and cutting as usual. Creatures vulnerable to fire will suffer double damage. When the magic elapses, the weapon returns to its normal S.D.C. form.', NULL, 'living-fire'),
  ('Living Fire: Healing Fire', 6, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.116', 'rifts', 'Touch; those to be healed must slowly pass through the fire.', 'The healing property of the fire lasts for one minute per level of the spell caster. Approximately 20 people can pass through the healing fire per minute. Preparation Time: At least 3D4 minutes to prepare the bonfire and light it with "new fire."', NULL, NULL, NULL, NULL, 'First a New Fire must be made (uses up all the melee actions for one round). Once the "pure" flame is created, it is used to light a bonfire while the sorcerer casts his second spell to create a Healing Fire. The magic causes the wood for the bonfire to ignite immediately and completely into a raging (but controlled) fire. When the fire is roaring, and the edges of the flame are a greenish color, the magic is ready. People who enter the fire pause for a couple of seconds, and continue to pass through it in a forward direction (never back the same way they entered, or the magic has no effect). Those passing through the fire are not burned, but instantly healed of 3D6 Hit Points and 2D6 S.D.C. The same individual can only pass through the same Healing Fire twice. The second time only 1D6 H.P. and S.D.C. are restored. After that, the flame, while tinged with green, does not burn, but neither does it heal. Those sick from disease can also be helped: 2D6 H.P. are restored, symptoms are reduced by half and the duration of the disease (and remaining penalties) is reduced in half. A sick individual can only be helped once. Afterward, the flame does not burn, but neither does it heal. Note: Has no effect on magical illnesses, illness caused by magical spoiling, or curses. Animals can also be chased through the flame to heal them of injury or to purge them of disease (completely kills disease in animals). Humans and mortal D-bees possessed by a supernatural force scream as they pass through the flame and a demonic image will, for an instant, appear in the fire around them. These individuals receive no healing, but if held in the fire for one minute, an exorcism will occur with a +20% chance for success (otherwise equal to the Exorcism spell).', NULL, 'living-fire'),
  ('Living Fire: Rerun''s Celestial Fire Bolt', 6, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.116', 'rifts', 'Up to 900 feet (274 m) +100 feet (30.5 m) per level of the spell caster; line of vision.', 'Instant.', 'To man-made things and mortal beings, the bolt does 3D6 M.D. +1 M.D. per level of the spell caster, but to supernatural beings (demons, Deevals, entities, ghosts, angels, deities, alien intelligences, etc.) the damage is !D6xlO M.D. +2 additional M.D. per level of experience! Vampires suffer only 3D6 Hit Points, but supernatural creatures vulnerable to lightning take double damage, plus the lightning flash will reveal the true nature of the Unclean, Il''ya and other monsters who are revealed by lightning (the same is true of the Call Lightning spell).', 'Dodge at -5!', NULL, NULL, 'A large, fiery lightning bolt that rockets from the hand of the spell caster and said to be similar to those hurled by the ancient God of War, Perun. Level Seven', NULL, 'living-fire'),
  ('Living Fire: Ballistic Fire', 7, 25, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.116', 'rifts', '1000 feet (305 m) +10 additional feet (3 m) per level of experience.', 'Instant', '1D6 M.D. per fiery missile', 'None', NULL, NULL, 'Ballistic Fire is an anti-infantry spell designed to mow down large numbers all at once. The spell creates one fiery missile per level of the spell caster which can then be directed and fired simultaneously at whatever multiple targets the mage desires. Actually, these missiles can be directed at several different targets (as few as one target per missile) as volleys of several missiles directed at two or more targets, or all concentrated as one large volley to all hit the same target. The balls of fire are magically guided and never miss! Regardless of the missiles created and the way they are distributed, the attack of Ballistic Fire takes only a single spell attack (approximately 7 seconds).', 'Ballistic Fire', 'living-fire'),
  ('Living Fire: Bonfire of Expulsion', 7, 35, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.116', 'rifts', 'Touch and requires "New Fire."', 'Results in one melee round; the fire lasts as long as it is nurtured (i.e. wood is added, the fire stoked, etc.), up to 48 hours.', NULL, 'Supernatural beings, Faerie Folk and Woodland Spirits are all -1 to save per level of the spell caster.', NULL, NULL, 'First a New Fire must be made (uses up all the melee actions for one round). Once the "pure" flame is created, it is used to light a bonfire while the sorcerer casts his second spell to create a Bonfire of Expulsion. The magic causes the wood for the bonfire to ignite immediately and completely into a raging (but controlled) fire. All lesser demons, sub-demons, entities, Faerie Folk and evil Russian Woodland Spirits who fail to save vs magic (note the substantial penalty to save) fear the pure fire and must flee the area - running at least 2D6 miles (3.2 to 19 km) away. They will not come any closer for the next 1D4 days +12 hours per level of the spell caster, or as long as the bonfire burns. Moreover, many will become so frightened or bored from the wait that they will leave the immediate area in search of easier fun. This magic is typically used to at least temporarily purge evil spirits and minor demons from a farmstead or village. The Bonfire of Expulsion, when used as a campfire, will also keep such creatures away from camp, and serves to notify such superhuman beings that a Fire Sorcerer, Old Believer, or Born Mystic protects this place. Unfortunately, it also puts them on notice and may invoke their ire. Note: The magic fire has no effect on other magical creatures, including Demon lords, vampires, demigods, gods, angels, or elementals. Nor are greater demons of 5th level experience or higher, affected. Inexperienced greater demons must save vs magic but at half the penalty noted previously. Lesser supernatural creatures that successfully save vs magic cannot come within 1200 feet (366 m) of the bonfire but can try long-range attacks or cause trouble in the surrounding area. Greater demons who save vs the magical bonfire are not held at bay, but are -1 on initiative and -1 attack per melee round.', NULL, 'living-fire'),
  ('Living Fire: Fire Gout', 7, 20, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.117', 'rifts', '30 feet (9 m) per level of experience.', 'Instant', '6D6 M.D. +1 per level of experience.', 'Dodge', NULL, NULL, 'The caster can magically conjure and direct a stream of fire similar to a flamethrower, only wider and can be fired straight up into the sky. It can be directed with a wave of the hands - point and shoot. The fiery stream extends the full length of its range (stopped or blocked only by large obstacles in its path) and is about three feet (0.9 m) in diameter. The intended target can attempt to dodge but is -3 to do so. There is a 01-70% likelihood that combustible materials will be set on fire.', 'Fire Gout', 'living-fire'),
  ('Living Fire: Perun''s Fire Scourge', 7, 25, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.117', 'rifts', 'By touch or up to 100 feet (30.5 m) +30 feet (9 m) per level of experience.', 'The blast is instant, the continuing fire varies.', '1D4 M.D. per level of experience against mortal creatures and S.D.C. objects. Against the supernatural, the magic is devastating: The initial blast does 1D6 M.D. per level of the spell caster, but the demon is also set on fire for one full melee round per level of the spell caster, inflicting 6D6 M.D. damage per round; double damage against Alien Intelligences and their avatars or life essences. Note: Supernatural creatures of fire and lightning, including elementals and fire demons, take only half damage from the initial blast and are not set on fire. Only completely immersing oneself in water or using the magic spells Extinguish Fire, Negate Magic and Anti-Magic Cloud can extinguish the magic fire before its duration of damage expires. Of course, the spell caster can extinguish it at will.', 'Dodge at -3.', NULL, NULL, 'This magic creates a small, fiery lightning bolt that shoots from the hand and is truly effective against demons, Deevals and other supernatural beings. Creatures of magic, like the dragon, sphinx and Faerie Folk, only suffer 1D6 M.D. +1 M.D. per level of experience of the spell caster. Level Eight', NULL, 'living-fire'),
  ('Living Fire: The Torch & Wheel', 8, 40, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.117', 'rifts', 'Varies', '24 hours or as long as it takes to complete the ritual.', NULL, 'Not applicable.', NULL, NULL, 'A purification ritual magic used to dispel illness on people or crops. A pole is put in the center of a wagon wheel with two torches attached to it. The wheel is then and rolled around the village without stopping until the circle is completed. The pace can be fast or leisurely, depending on the spell caster and the urgency of the situation. If both torches stay lit the entire time, it means that the village and all within the circle (including animals, food, stored grain, etc.) are free of disease or magic spoiling. The completing of this ritual also makes all within +3 to save vs disease and magical spoiling for 48 hours. If one torch goes out before the circle is completed it means spoiling magic and/or disease or blight is present. The wheel, with its one lit torch, will magically roll to each food or place of contamination. If both torches go out, it is a sign that either demons or a powerful witch (6th level or higher) is somewhere within the circle. However, the wheel does not locate such supernatural or magical pestilence. Level Nine', NULL, 'living-fire'),
  ('Living Fire: Desiccate the Supernatural', 9, 50, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.117', 'rifts', 'One up to 50 feet (15.2 m) away per level of experience, or two by touch.', 'Instant', '2D4x10 M.D. (or Hit Points, whichever is appropriate).', '-1 to save', NULL, NULL, 'Desiccate is a vicious spell designed for use against supernatural monsters. It will not work against any opponent in full environmental armor (body armor or power armor), or safely locked in an armored M.D.C. vehicle or room. Likewise, it will not work against ordinary mortals, human or D-bee, only supernatural beings, good or evil, including spirits in physical form, sub-demons (Gargoyles, Brodkil, etc.), demons, deevils, elementals, Spirits of Light (elementals), demigods, gods, avatars (the life essences of alien intelligences, including vampires), angels, and others. It is important to note that the sphinx, dragons, unicorns, faerie folk and a handful of other superhuman beings possessing supernatural strength and abilities, but known as "Creatures of Magic," are not true supernatural creatures (they are more magical than supernatural, or at least not in the same way as demons and gods) and are immune to this magic. The spell works by drawing moisture out of the target, killing it in a matter of 2D4 seconds, and hopefully reducing it to a withered husk. Regenerating creatures will be unable to bio-regenerate damage caused by this spell until they replenish then- body''s water supply. Creatures that do not incorporate water in their bodies (i.e. pure energy) will not be harmed by this spell. Water Elementals suffer double damage. A successful save vs magic means the creature suffers half damage.', 'Desiccate the Supernatural', 'living-fire'),
  ('Living Fire: Dragonfire', 9, 20, '20 P.P.E. for the Fire Sorcerer, 40 for other magic', NULL, 'import', 'Rifts World Book 18: Mystic Russia p.118', 'rifts', '100 feet (30.5 m)', 'One melee round per level of experience.', '!D4xlO M.D.', 'None except dodge, but the victim must know the attack is coming and must roll a 16 or higher.', NULL, NULL, 'O.C.C.s. This spell allows the caster to temporarily breathe fire just like an adult Fire Dragon. Every melee round that the spell is in effect, the mage is able to breathe as many as two searing blasts of fire that each inflict !D4xlO M.D. The Dragonfire blasts are magically directed and seldom miss. For the spell to work, there can be nothing blocking the caster''s mouth, no helmet, gas mask, etc. Level Twelve', NULL, 'living-fire'),
  ('Living Fire: Metamorphosis: Smoke', 12, 220, NULL, NULL, 'import', 'Rifts World Book 18: Mystic Russia p.118', 'rifts', 'Self', '20 minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'Said to be one of the most powerful of all the metamorph magics, the mage can transform himself into a swirling cloud of smoke. As such, no physical or energy attacks can harm him. No locked door can stop him, for he can slip through the tiniest crack or keyhole. Although the mage can not communicate or cast magic in this form, he can hear and see events around him as would a normal human being. Of course, he can materialize (naked) with but a thought. The smoke moves at a maximum speed of 14. Prowls (natural, innate ability) at an 80% skill proficiency, is completely silent, can hover up to 200 feet (61 m) high and can be carried by the wind. The smoke resembles the grey smoke that rises from burning wood or charcoal. The vision of those who step into the smoke cloud is obscured (-2 on initiative, -2 to strike, parry and dodge), but the smoke is not as dense as real smoke, and does not cause people to cough or choke on its fumes.', NULL, 'living-fire');

-- Read the result back. Each batch asserts its OWN rows and nothing else: a
-- cross-batch assertion is an assertion about execution order in disguise, and
-- data scripts run in filename order rather than in batch order.
SELECT 'fire spells inserted' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE tradition = 'living-fire';

SELECT 'every one is prefixed' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE tradition = 'living-fire' AND name LIKE 'Living Fire: %';

SELECT 'every one cites this book by page' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE tradition = 'living-fire' AND source_book LIKE 'Rifts World Book 18: Mystic Russia p.%';

SELECT 'every one carries a cost' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE tradition = 'living-fire' AND ppe > 0;

SELECT 'every one carries a description' AS assertion, count(*) AS got, 39 AS want
  FROM spells WHERE tradition = 'living-fire' AND length(description) > 40;

SELECT 'the schedules carry their note' AS assertion, count(*) AS got, 7 AS want
  FROM spells WHERE tradition = 'living-fire' AND ppe_note IS NOT NULL;

SELECT 'the retellings are linked' AS assertion, count(*) AS got, 13 AS want
  FROM spells WHERE tradition = 'living-fire' AND same_spell_as IS NOT NULL;

SELECT 'and every link resolves to a real row' AS assertion, count(*) AS got, 0 AS want
  FROM spells r WHERE r.tradition = 'living-fire' AND r.same_spell_as IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM spells t WHERE t.name = r.same_spell_as);

SELECT 'no row outside this book was written' AS assertion, count(*) AS got, 0 AS want
  FROM spells WHERE tradition = 'living-fire' AND source <> 'import';

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('zzzzzzzzzz-mr-living-fire-spells.sql');
